<?php
require_once '../includes/farmacia.php';exigirPermiso('proveedores.ver');$db=farmaciaDb();
$q=trim((string)($_GET['q']??''));$pagina=max(1,(int)($_GET['pagina']??1));$params=['%'.$q.'%','%'.$q.'%'];$where=' WHERE Nombre LIKE ? OR NIT LIKE ?';
$stmt=$db->prepare('SELECT COUNT(*) FROM Proveedores'.$where);$stmt->execute($params);$total=(int)$stmt->fetchColumn();$paginas=max(1,(int)ceil($total/20));$pagina=min($pagina,$paginas);
$stmt=$db->prepare('SELECT * FROM Proveedores'.$where.' ORDER BY Nombre LIMIT 20 OFFSET '.(($pagina-1)*20));$stmt->execute($params);$filas=$stmt->fetchAll(PDO::FETCH_ASSOC);
$titulo='Proveedores';require '../includes/header.php';
?>
<h1 class="page-title"><i class="bi bi-truck"></i> Proveedores</h1>
<?php if(isset($_GET['guardado'])): ?><div class="alert alert-success">Proveedor guardado correctamente.</div><?php endif; ?>
<div class="card"><div class="card-header d-flex justify-content-between"><span>Listado de proveedores</span><?php if(tienePermiso('proveedores.editar')): ?><a class="btn btn-light btn-sm" href="nuevo.php">Nuevo proveedor</a><?php endif; ?></div><div class="card-body"><form method="get" class="input-group mb-3"><input class="form-control" name="q" value="<?=h($q)?>" placeholder="Buscar por nombre o NIT" aria-label="Buscar proveedor"><button class="btn btn-primary">Buscar</button></form><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Nombre</th><th>NIT</th><th>Teléfono</th><th>Email</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($filas as $p): ?><tr><td><?=h($p['Nombre'])?></td><td><?=h($p['NIT'])?></td><td><?=h($p['Telefono'])?></td><td><?=h($p['Email'])?></td><td><?=$p['Activo']?'Activo':'Inactivo'?></td><td><a class="btn btn-info btn-sm" href="ver.php?id=<?=$p['ProveedorID']?>">Ver</a> <?php if(tienePermiso('proveedores.editar')): ?><a class="btn btn-warning btn-sm" href="editar.php?id=<?=$p['ProveedorID']?>">Editar</a><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$filas): ?><tr><td colspan="6" class="text-center text-muted">No hay proveedores para mostrar.</td></tr><?php endif; ?></tbody></table></div><div class="d-flex justify-content-between"><span><?=$total?> proveedores · Página <?=$pagina?> de <?=$paginas?></span><div><?php foreach(['Anterior'=>$pagina-1,'Siguiente'=>$pagina+1] as $label=>$p): if($p>=1&&$p<=$paginas): ?><a class="btn btn-outline-primary btn-sm" href="?<?=h(http_build_query(['q'=>$q,'pagina'=>$p]))?>"><?=$label?></a> <?php endif; endforeach; ?></div></div></div></div>
